import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"ADR-0001: Use JdbcTemplate over JPA/Hibernate","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-use-jdbc-template-over-jpa.md","filePath":"adr/0001-use-jdbc-template-over-jpa.md"}'),i={name:"adr/0001-use-jdbc-template-over-jpa.md"};function n(l,e,s,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0001-use-jdbctemplate-over-jpa-hibernate" tabindex="-1">ADR-0001: Use JdbcTemplate over JPA/Hibernate <a class="header-anchor" href="#adr-0001-use-jdbctemplate-over-jpa-hibernate" aria-label="Permalink to &quot;ADR-0001: Use JdbcTemplate over JPA/Hibernate&quot;">​</a></h1><p><strong>Date:</strong> 2026-06-12 <strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>При выборе способа доступа к данным для сервера Mozhno рассматривались два варианта: Spring Data JPA/Hibernate и прямой JDBC через <code>JdbcTemplate</code>.</p><p>Mozhno — это сервер фиче-флагов, критичный к latency: SDK-клиенты запрашивают правила флагов на каждый запрос. Доменная модель относительно проста: 15 таблиц, чёткие связи, никаких сложных графов объектов.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Выбран <strong>Spring <code>JdbcTemplate</code></strong> с ручным написанием SQL и <code>RowMapper</code>.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Позитивные:</strong></p><ul><li>Полный контроль над каждым SQL-запросом. Никаких сгенерированных LEFT JOIN на 5 таблиц из-за <code>FetchType.EAGER</code>.</li><li>Никаких <code>LazyInitializationException</code> в продакшене.</li><li>Прямой <code>INSERT ... RETURNING id</code> вместо <code>currval()</code> для получения сгенерированных ключей.</li><li>Прозрачная производительность: каждый запрос виден в коде, легко добавить индекс или переписать запрос.</li><li>Отсутствие ORM-зависимости упрощает потенциальную миграцию на другие БД.</li></ul><p><strong>Негативные:</strong></p><ul><li>Больше ручного кода (RowMapper, SQL-строки).</li><li>Нет автоматической валидации схемы на старте (компенсируется Flyway).</li><li>Нет кеша первого уровня / dirty checking (компенсируется явным Caffeine-кешем).</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><ul><li><strong>Spring Data JPA:</strong> Отклонён из-за риска N+1 запросов, сложности с нативными RETURNING для PostgreSQL, потери контроля над SQL.</li><li><strong>jOOQ:</strong> Избыточен для 15 таблиц. Добавляет кодогенерацию.</li><li><strong>MyBatis:</strong> Разумная альтернатива, но требует XML-маппингов. JdbcTemplate достаточен.</li></ul>',14)])])}const b=a(i,[["render",n]]);export{u as __pageData,b as default};
